import{_ as o,c as d,o as t,b2 as c}from"./chunks/framework.CUhoHPxN.js";const b=JSON.parse('{"title":"代码生成设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-16-codegen-design.md","filePath":"superpowers/specs/2026-05-16-codegen-design.md"}'),a={name:"superpowers/specs/2026-05-16-codegen-design.md"};function r(n,e,l,i,s,p){return t(),d("div",null,[...e[0]||(e[0]=[c(`<h1 id="代码生成设计文档" tabindex="-1">代码生成设计文档 <a class="header-anchor vp-link" href="#代码生成设计文档" aria-label="Permalink to &quot;代码生成设计文档&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>在 <code>quickboot</code> + <code>quick-ui</code> 中实现《代码生成需求文档》所述能力：基于数据库表管理生成元数据，支持导入、创建表、编辑配置、预览、同步库表结构、Zip 下载生成代码。</p><p>实现策略：<strong>库表内省</strong>使用 <strong>MyBatis-Plus Generator 3.5.15</strong>（<code>ConfigBuilder</code> / <code>TableInfo</code>）；<strong>代码产出</strong>由 <strong>FreeMarker</strong> 自定义模板渲染并 Zip 下载；对外 API 与生成物对齐当前仓库分层（<code>domain</code> / <code>dto</code> / <code>vo</code>、<code>R&lt;T&gt;</code>、POST 删改、Sa-Token、<code>C7</code> + <code>DESIGN.md</code>）。OpenSpec 真源：<code>openspec/changes/add-code-gen/</code>。</p><p>路径与权限以需求文档为真源：<code>/tool/gen/*</code>、<code>tool:gen:list|import|create|edit|remove|preview|code</code>。</p><h2 id="_2-已确认决策摘要" tabindex="-1">2. 已确认决策摘要 <a class="header-anchor vp-link" href="#_2-已确认决策摘要" aria-label="Permalink to &quot;2. 已确认决策摘要&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>决策</th></tr></thead><tbody><tr><td>API 前缀与权限</td><td><code>/tool/gen</code>，<code>tool:gen:*</code>（见 §6.2）</td></tr><tr><td>实现策略</td><td>迁移旧 generator 核心 + 适配 quickboot2；<strong>不</strong>整体引入 RuoYi Velocity 模板</td></tr><tr><td>生成物风格</td><td>对齐 <code>SysNotice</code> / <code>SysOperLog</code> 等现有模块 + <code>quick-ui</code> C7 组件</td></tr><tr><td>HTTP 动词</td><td><strong>对外路径</strong>与需求一致；<strong>修改/删除</strong>用 <strong>POST</strong>（需求 <code>PUT</code>/<code>DELETE</code> 不对外暴露，以本设计为准）</td></tr><tr><td>生成方式</td><td>首期仅 <strong>Zip 下载</strong>（默认文件名 <code>ruoyi.zip</code>）；自定义路径写盘二期</td></tr><tr><td>表结构与能力</td><td>若依语义 <code>gen_table</code> / <code>gen_table_column</code>；<strong>单表 CRUD 模板</strong>；树表/主子表字段可配置，<strong>模板二期</strong></td></tr><tr><td>建表 SQL</td><td>首期支持；仅允许 <code>CREATE TABLE</code>；Druid 解析 + <code>tool:gen:create</code></td></tr><tr><td>模板引擎</td><td><strong>FreeMarker</strong>（<code>classpath:vm/quickboot/**/*.ftl</code>）</td></tr><tr><td>模块落点</td><td>首期集中在 <code>quickboot-web</code> 包 <code>io.github.genkidoudou.web.tool.gen</code></td></tr></tbody></table></div><h2 id="_3-方案选型" tabindex="-1">3. 方案选型 <a class="header-anchor vp-link" href="#_3-方案选型" aria-label="Permalink to &quot;3. 方案选型&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>方案</th><th>说明</th><th>结论</th></tr></thead><tbody><tr><td><strong>A（采用）</strong></td><td>迁移旧 <code>CodeGenerator</code> + 元数据 CRUD + 重写 FreeMarker 模板</td><td>与决策一致；导入/同步/预览逻辑已验证</td></tr><tr><td>B</td><td>迁移 Service，元数据改用 MP Generator / JDBC 内省</td><td>默认值规则需重造，风险高</td></tr><tr><td>C</td><td>引入 RuoYi Velocity 模板 + 适配层</td><td>与当前仓库风格冲突大</td></tr></tbody></table></div><h2 id="_4-范围与非范围" tabindex="-1">4. 范围与非范围 <a class="header-anchor vp-link" href="#_4-范围与非范围" aria-label="Permalink to &quot;4. 范围与非范围&quot;">​</a></h2><h3 id="_4-1-范围" tabindex="-1">4.1 范围 <a class="header-anchor vp-link" href="#_4-1-范围" aria-label="Permalink to &quot;4.1 范围&quot;">​</a></h3><ul><li>Flyway：<code>gen_table</code>、<code>gen_table_column</code>、菜单与按钮权限种子。</li><li>后端：<code>GenController</code> 及 Service / Mapper / Domain / Bo / Vo；<code>DbIntrospector</code>、<code>GenTemplateRenderer</code>、<code>GenZipExporter</code>。</li><li>FreeMarker 模板：单表 CRUD 后端全套 + <code>api.js</code> + C7 列表页 + <strong>三 Tab 编辑配置页</strong>（基本信息 / 字段信息 / 生成信息）。</li><li><code>quick-ui</code>：<code>api/tool/gen.js</code>、<code>views/tool/gen/index.vue</code>、<code>views/tool/gen/edit.vue</code>（及导入/创建表/预览弹窗）。</li><li>配置：<code>application.yml</code> 中 <code>quickboot.gen.*</code>；可选与 <code>sys_config</code> 键（如作者、默认包名）联动。</li></ul><h3 id="_4-2-非范围-本期不做" tabindex="-1">4.2 非范围（本期不做） <a class="header-anchor vp-link" href="#_4-2-非范围-本期不做" aria-label="Permalink to &quot;4.2 非范围（本期不做）&quot;">​</a></h3><ul><li><code>GET /tool/gen/genCode/{tableName}</code> 自定义路径写盘（可返回明确「未开放」或 501）。</li><li><code>tpl_category=tree</code> / 主子表 <strong>代码模板</strong>（配置可保存；生成时提示「树表模板尚未开放」）。</li><li>生成结果自动 <code>INSERT sys_menu</code>（可提供 <code>menu.sql.ftl</code> 片段供手工执行）。</li><li>将 generator 下沉到 <code>quickboot-common</code>（除非后续多模块复用再抽）。</li></ul><h2 id="_5-架构与模块边界" tabindex="-1">5. 架构与模块边界 <a class="header-anchor vp-link" href="#_5-架构与模块边界" aria-label="Permalink to &quot;5. 架构与模块边界&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>quick-ui (views/tool/gen, api/tool/gen.js)</span></span>
<span class="line"><span>        │  R&lt;T&gt; / PageInfo；Zip 为 blob 下载</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>quickboot-web … tool.gen</span></span>
<span class="line"><span>  ├── controller   GenController  @RequestMapping(&quot;/tool/gen&quot;)</span></span>
<span class="line"><span>  ├── service      GenTableService / GenTableColumnService</span></span>
<span class="line"><span>  ├── mapper       GenTableMapper, GenTableColumnMapper</span></span>
<span class="line"><span>  ├── domain       GenTable, GenTableColumn</span></span>
<span class="line"><span>  └── support</span></span>
<span class="line"><span>        ├── DbIntrospector       ← 自 old CodeGenerator 精简迁入</span></span>
<span class="line"><span>        ├── GenTemplateRenderer  ← FreeMarker</span></span>
<span class="line"><span>        └── GenZipExporter       ← 内存 ZipOutputStream，不落盘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><strong>依赖</strong>：Druid SQL 解析（建表）、FreeMarker、JDK Zip。</p><p><strong>配置项（<code>quickboot.gen</code>）</strong>：</p><div class="vp-table"><table><thead><tr><th>配置键</th><th>说明</th><th>默认建议</th></tr></thead><tbody><tr><td><code>author</code></td><td>生成注释作者</td><td>可覆盖为 <code>sys_config</code> 中 <code>gen.author</code></td></tr><tr><td><code>package-name</code></td><td>Java 根包</td><td><code>io.github.genkidoudou.web</code></td></tr><tr><td><code>module-name</code></td><td>默认模块名</td><td><code>system</code></td></tr><tr><td><code>zip-file-name</code></td><td>下载文件名</td><td><code>ruoyi.zip</code></td></tr><tr><td><code>create-table-max-statements</code></td><td>单次建表语句上限</td><td><code>10</code></td></tr></tbody></table></div><h2 id="_6-数据模型" tabindex="-1">6. 数据模型 <a class="header-anchor vp-link" href="#_6-数据模型" aria-label="Permalink to &quot;6. 数据模型&quot;">​</a></h2><h3 id="_6-1-gen-table" tabindex="-1">6.1 <code>gen_table</code> <a class="header-anchor vp-link" href="#_6-1-gen-table" aria-label="Permalink to &quot;6.1 \`gen_table\`&quot;">​</a></h3><p>主键策略与 <code>V1__baseline</code> 等现有表一致（实现阶段对照 Flyway 定稿，建议 <code>BIGINT</code> + 雪花）。</p><div class="vp-table"><table><thead><tr><th>列 / 含义</th><th>说明</th></tr></thead><tbody><tr><td><code>table_id</code></td><td>主键</td></tr><tr><td><code>table_name</code></td><td>表名称；<strong>唯一</strong></td></tr><tr><td><code>table_comment</code></td><td>表描述</td></tr><tr><td><code>class_name</code></td><td>实体类名</td></tr><tr><td><code>tpl_category</code></td><td>模板类型，默认 <code>crud</code>；<code>tree</code> 仅保存配置</td></tr><tr><td><code>tpl_web_type</code></td><td>前端模板类型，固定 <code>element-plus</code></td></tr><tr><td><code>package_name</code></td><td>生成包路径</td></tr><tr><td><code>module_name</code></td><td>模块名</td></tr><tr><td><code>business_name</code></td><td>业务名（路由/权限片段）</td></tr><tr><td><code>function_name</code></td><td>功能名</td></tr><tr><td><code>function_author</code></td><td>作者</td></tr><tr><td><code>gen_type</code></td><td><code>0</code> Zip / <code>1</code> 自定义路径（首期仅 <code>0</code> 生效）</td></tr><tr><td><code>gen_path</code></td><td>自定义路径（二期）</td></tr><tr><td><code>parent_menu_id</code></td><td>上级菜单 ID</td></tr><tr><td><code>tree_code</code> / <code>tree_parent_code</code> / <code>tree_name</code></td><td>树表字段（配置用，模板二期）</td></tr><tr><td><code>sub_table_name</code> / <code>sub_table_fk_name</code></td><td>主子表（二期）</td></tr><tr><td><code>options</code></td><td>JSON 扩展，可空</td></tr><tr><td><code>remark</code></td><td>备注</td></tr><tr><td><code>create_by</code> / <code>create_time</code> / <code>update_by</code> / <code>update_time</code></td><td>审计字段</td></tr></tbody></table></div><h3 id="_6-2-gen-table-column" tabindex="-1">6.2 <code>gen_table_column</code> <a class="header-anchor vp-link" href="#_6-2-gen-table-column" aria-label="Permalink to &quot;6.2 \`gen_table_column\`&quot;">​</a></h3><p>对齐若依 + 旧栈：<code>column_id</code>、<code>table_id</code>、<code>column_name</code>、<code>column_comment</code>、<code>column_type</code>、<code>java_type</code>、<code>java_field</code>、<code>is_pk</code>、<code>is_increment</code>、<code>is_required</code>、<code>is_insert</code>、<code>is_edit</code>、<code>is_list</code>、<code>is_query</code>、<code>query_type</code>、<code>html_type</code>、<code>dict_type</code>、<code>sort</code>、审计字段。</p><p><strong><code>is_*</code> 语义</strong>：与若依一致，<code>1</code> 表示「是」、<code>0</code> 表示「否」（导入时修正旧栈个别反转逻辑）。</p><h3 id="_6-3-flyway-与菜单" tabindex="-1">6.3 Flyway 与菜单 <a class="header-anchor vp-link" href="#_6-3-flyway-与菜单" aria-label="Permalink to &quot;6.3 Flyway 与菜单&quot;">​</a></h3><p>迁移文件编号以实现时递增为准（如 <code>V18__gen_table.sql</code>）：</p><ul><li>建表 + 索引（<code>table_name</code> 唯一）。</li><li>菜单：<strong>目录</strong>「系统工具」（<code>M</code>，如 <code>menu_id=2100</code>）→ <strong>菜单</strong>「代码生成」（<code>C</code>，<code>path=tool/gen</code>，<code>component=tool/gen/index</code>，<code>perms=tool:gen:list</code>）。</li><li><strong>按钮</strong>：<code>tool:gen:import</code>、<code>tool:gen:create</code>、<code>tool:gen:edit</code>、<code>tool:gen:remove</code>、<code>tool:gen:preview</code>、<code>tool:gen:code</code>。</li><li>为超级管理员角色授权（与 <code>V16</code>/<code>V17</code> 监控菜单做法一致）。</li></ul><h2 id="_7-核心业务流" tabindex="-1">7. 核心业务流 <a class="header-anchor vp-link" href="#_7-核心业务流" aria-label="Permalink to &quot;7. 核心业务流&quot;">​</a></h2><h3 id="_7-1-导入表" tabindex="-1">7.1 导入表 <a class="header-anchor vp-link" href="#_7-1-导入表" aria-label="Permalink to &quot;7.1 导入表&quot;">​</a></h3><ol><li><code>GET /tool/gen/db/list</code> 返回库表候选（支持表名、表描述筛选），<strong>排除已导入</strong>的 <code>table_name</code>。</li><li><code>POST /tool/gen/importTable</code> 接收表名列表；<strong>空列表</strong> → <code>WarningException</code> + 前端提示。</li><li><code>DbIntrospector</code> 读取表/列 → <code>converTableInfo</code> / <code>converTableField</code>（沿用旧栈默认规则：主键、<code>remark</code>、<code>create_by</code>、<code>del_flag</code>、<code>create_time</code>、字典注释 <code>[dict_type]</code> 等）→ 写入 <code>gen_table</code> + <code>gen_table_column</code>。</li></ol><h3 id="_7-2-创建表" tabindex="-1">7.2 创建表 <a class="header-anchor vp-link" href="#_7-2-创建表" aria-label="Permalink to &quot;7.2 创建表&quot;">​</a></h3><ol><li><code>POST /tool/gen/createTable</code>，Body：<code>{ &quot;sql&quot;: &quot;...&quot; }</code>。</li><li>Druid 解析，<strong>仅执行</strong> <code>MySqlCreateTableStatement</code>；拒绝 <code>DROP</code>/<code>ALTER</code>/<code>INSERT</code> 等。</li><li>执行成功后<strong>不自动 import</strong>；用户从「导入表」选择新表。</li></ol><h3 id="_7-3-编辑保存" tabindex="-1">7.3 编辑保存 <a class="header-anchor vp-link" href="#_7-3-编辑保存" aria-label="Permalink to &quot;7.3 编辑保存&quot;">​</a></h3><ol><li><code>GET /tool/gen/{tableId}</code> 返回表头 + <code>columns</code>。</li><li><code>POST /tool/gen/update</code>：校验基本信息与生成信息表单（Jakarta Validation）→ 更新表头 + 批量更新列配置。</li></ol><h3 id="_7-4-同步数据库" tabindex="-1">7.4 同步数据库 <a class="header-anchor vp-link" href="#_7-4-同步数据库" aria-label="Permalink to &quot;7.4 同步数据库&quot;">​</a></h3><ol><li><code>GET /tool/gen/synchDb/{tableName}</code>：按库表重读结构 → 更新 <code>gen_table</code> 表头 → <strong>删除并重建</strong> 该表 <code>gen_table_column</code> 行（与旧栈一致）。</li></ol><h3 id="_7-5-预览与生成" tabindex="-1">7.5 预览与生成 <a class="header-anchor vp-link" href="#_7-5-预览与生成" aria-label="Permalink to &quot;7.5 预览与生成&quot;">​</a></h3><ol><li>组装 <code>GenContext</code>（表、列、包路径、权限前缀 <code>{module}:{business}</code> 等）。</li><li><strong>预览</strong>：<code>GET /tool/gen/preview/{tableId}</code> → <code>List&lt;GenPreviewVo&gt;</code>，项为 <code>templateName</code> + <code>content</code>；前端 Tab 展示 + <strong>复制</strong>。</li><li><strong>生成</strong>：<code>GET /tool/gen/batchGenCode?tables=table1,table2</code> → <code>application/zip</code>，默认 <code>ruoyi.zip</code>；流式内存打包，<strong>不写服务端业务目录</strong>。</li><li>若 <code>tpl_category=tree</code>：生成接口返回明确业务错误「树表模板尚未开放」。</li></ol><h3 id="_7-6-删除" tabindex="-1">7.6 删除 <a class="header-anchor vp-link" href="#_7-6-删除" aria-label="Permalink to &quot;7.6 删除&quot;">​</a></h3><p><code>POST /tool/gen/remove/{tableId}</code>：仅删除元数据，<strong>不删除</strong>物理库表。</p><h2 id="_8-后端接口契约" tabindex="-1">8. 后端接口契约 <a class="header-anchor vp-link" href="#_8-后端接口契约" aria-label="Permalink to &quot;8. 后端接口契约&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>方法</th><th>路径</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/tool/gen/list</code></td><td><code>tool:gen:list</code></td><td>分页；条件：表名、表描述、创建时间区间</td></tr><tr><td>GET</td><td><code>/tool/gen/db/list</code></td><td><code>tool:gen:list</code></td><td>库表候选列表</td></tr><tr><td>GET</td><td><code>/tool/gen/{tableId}</code></td><td><code>tool:gen:list</code></td><td>详情含 <code>columns</code></td></tr><tr><td>POST</td><td><code>/tool/gen/update</code></td><td><code>tool:gen:edit</code></td><td>保存配置（对应需求 PUT）</td></tr><tr><td>POST</td><td><code>/tool/gen/importTable</code></td><td><code>tool:gen:import</code></td><td>导入；<code>tables</code> 逗号分隔或 JSON 数组</td></tr><tr><td>POST</td><td><code>/tool/gen/createTable</code></td><td><code>tool:gen:create</code></td><td>执行建表 SQL</td></tr><tr><td>GET</td><td><code>/tool/gen/preview/{tableId}</code></td><td><code>tool:gen:preview</code></td><td>预览</td></tr><tr><td>POST</td><td><code>/tool/gen/remove/{tableId}</code></td><td><code>tool:gen:remove</code></td><td>删除元数据（对应需求 DELETE）</td></tr><tr><td>GET</td><td><code>/tool/gen/synchDb/{tableName}</code></td><td><code>tool:gen:edit</code></td><td>同步库表结构</td></tr><tr><td>GET</td><td><code>/tool/gen/batchGenCode</code></td><td><code>tool:gen:code</code></td><td>Zip 下载；query <code>tables</code></td></tr><tr><td>GET</td><td><code>/tool/gen/genCode/{tableName}</code></td><td><code>tool:gen:code</code></td><td><strong>二期</strong>；首期未实现</td></tr></tbody></table></div><p><strong>通用约定</strong>：</p><ul><li>除 Zip 外统一 <code>R&lt;T&gt;</code> / <code>PageInfo</code>。</li><li><code>@Tag(&quot;代码生成&quot;)</code>、<code>@Operation</code>、<code>@Parameter</code>、<code>@SaCheckPermission</code>。</li><li>业务失败使用 <code>WarningException</code> + <code>ErrorCodes.Gen.*</code>；禁止 <code>IllegalArgumentException</code> 作为业务信号。</li><li><code>/tool/gen/**</code> 建议 <code>@IgnoreLogger(ALL)</code>，避免操作日志噪声。</li></ul><h2 id="_9-代码模板-首期" tabindex="-1">9. 代码模板（首期） <a class="header-anchor vp-link" href="#_9-代码模板-首期" aria-label="Permalink to &quot;9. 代码模板（首期）&quot;">​</a></h2><p>模板目录：<code>quickboot-web/src/main/resources/vm/quickboot/</code>。</p><div class="vp-table"><table><thead><tr><th>模板文件</th><th>产出路径（Zip 内）</th></tr></thead><tbody><tr><td><code>domain.java.ftl</code></td><td><code>.../domain/{Class}.java</code></td></tr><tr><td><code>mapper.java.ftl</code> / <code>mapper.xml.ftl</code></td><td>Mapper 接口 + XML</td></tr><tr><td><code>service.java.ftl</code> / <code>serviceImpl.java.ftl</code></td><td>Service 层</td></tr><tr><td><code>controller.java.ftl</code></td><td>Controller（<code>R</code>、<code>POST</code> 删改、<code>@SaCheckPermission</code>）</td></tr><tr><td><code>queryBo.java.ftl</code> / <code>bo.java.ftl</code> / <code>vo.java.ftl</code></td><td>DTO</td></tr><tr><td><code>api.js.ftl</code></td><td><code>quick-ui/src/api/{module}/{business}.js</code></td></tr><tr><td><code>index.vue.ftl</code></td><td>C7JsonTable 列表页</td></tr><tr><td><code>menu.sql.ftl</code></td><td>菜单 SQL 片段（注释说明需手工执行）</td></tr></tbody></table></div><p><strong>不生成</strong>：旧栈 <code>entity</code>/<code>do</code>、Ruoyi <code>@PutMapping</code>/<code>@DeleteMapping</code>、非 C7 的独立 <code>add-or-update.vue</code>（编辑配置由代码生成<strong>管理页</strong> <code>edit.vue</code> 完成，与被生成业务模块的表单页区分）。</p><p><strong>生成 Controller 参考</strong>：<code>SysNoticeController</code>（分页 GET、详情 GET、增改 POST、删除 POST）。</p><p><strong>生成前端列表参考</strong>：<code>views/monitor/operlog/index.vue</code>、<code>views/system/notice</code>（C7JsonTable、权限指令、<code>DESIGN.md</code>）。</p><h2 id="_10-前端-quick-ui" tabindex="-1">10. 前端（<code>quick-ui</code>） <a class="header-anchor vp-link" href="#_10-前端-quick-ui" aria-label="Permalink to &quot;10. 前端（\`quick-ui\`）&quot;">​</a></h2><h3 id="_10-1-api" tabindex="-1">10.1 API <a class="header-anchor vp-link" href="#_10-1-api" aria-label="Permalink to &quot;10.1 API&quot;">​</a></h3><ul><li><code>src/api/tool/gen.js</code>：全部指向 <code>/tool/gen</code>（不得混用 <code>/generator/gentable</code>）。</li></ul><h3 id="_10-2-页面" tabindex="-1">10.2 页面 <a class="header-anchor vp-link" href="#_10-2-页面" aria-label="Permalink to &quot;10.2 页面&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>页面/组件</th><th>职责</th></tr></thead><tbody><tr><td><code>views/tool/gen/index.vue</code></td><td>列表：查询（表名、表描述、创建时间）；工具栏：批量生成、创建表、导入；行操作：预览、编辑、同步、删除</td></tr><tr><td><code>views/tool/gen/edit.vue</code></td><td>三 Tab：基本信息 / 字段表格（列配置）/ 生成信息；提交 <code>POST /tool/gen/update</code></td></tr><tr><td>导入弹窗</td><td><code>db/list</code> 多选；未选 <code>ElMessage.warning</code></td></tr><tr><td>创建表弹窗</td><td>SQL 文本域 → <code>createTable</code></td></tr><tr><td>预览弹窗</td><td>按模板名 Tab + 复制</td></tr></tbody></table></div><h3 id="_10-3-权限与路由" tabindex="-1">10.3 权限与路由 <a class="header-anchor vp-link" href="#_10-3-权限与路由" aria-label="Permalink to &quot;10.3 权限与路由&quot;">​</a></h3><ul><li><code>v-hasPermi</code> 与 <code>tool:gen:*</code> 一致。</li><li>编辑页路由隐藏（<code>activeMenu</code> 指向列表），与若依习惯一致。</li></ul><p>实现前须阅读 <code>DESIGN.md</code>、<code>sdd/前端代码规范.md</code>、<code>sdd/后端代码规范.md</code>（见 <code>AGENTS.md</code>）。</p><h2 id="_11-安全与错误码" tabindex="-1">11. 安全与错误码 <a class="header-anchor vp-link" href="#_11-安全与错误码" aria-label="Permalink to &quot;11. 安全与错误码&quot;">​</a></h2><p><strong>安全</strong></p><ul><li><code>createTable</code>：白名单语句类型；语句数上限（配置项）。</li><li>Zip：仅内存流；不写入 <code>gen_path</code> 等业务目录。</li><li><code>genCode</code> 写盘：首期不实现。</li></ul><p><strong>错误码（<code>ErrorCodes.Gen</code> 示例，实现阶段定稿）</strong></p><div class="vp-table"><table><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td>表已导入</td><td>重复 <code>importTable</code></td></tr><tr><td>表不存在</td><td><code>synchDb</code> / <code>preview</code> / <code>get</code></td></tr><tr><td>SQL 非法</td><td>非 CREATE TABLE 或解析失败</td></tr><tr><td>树模板未开放</td><td><code>tpl_category=tree</code> 且调用生成</td></tr><tr><td>导入未选表</td><td>与需求「未选择时阻断」一致</td></tr></tbody></table></div><h2 id="_12-测试与验收" tabindex="-1">12. 测试与验收 <a class="header-anchor vp-link" href="#_12-测试与验收" aria-label="Permalink to &quot;12. 测试与验收&quot;">​</a></h2><p>对齐需求文档 §9 及本设计扩展项：</p><ul><li>导入 / 创建表 / 编辑保存后返回列表并正确刷新。</li><li>预览内容与模板文件一一对应；<strong>复制</strong>可用。</li><li><code>batchGenCode</code> 下载成功，Zip 可解压，含预期后端与前端文件。</li><li>同步后列配置与库表一致。</li><li>菜单与 <code>tool:gen:*</code> 权限对 admin 可见可操作。</li><li>集成测试建议：<code>import</code> → <code>get</code> → <code>update</code> → <code>preview</code> 非空 → <code>batchGenCode</code> 解压校验关键路径。</li></ul><h2 id="_13-后续步骤" tabindex="-1">13. 后续步骤 <a class="header-anchor vp-link" href="#_13-后续步骤" aria-label="Permalink to &quot;13. 后续步骤&quot;">​</a></h2><p>在单独会话中按 <strong>writing-plans</strong> 产出 <code>docs/superpowers/plans/2026-05-16-codegen.md</code> 的实现任务清单后再编码。</p><hr><p><strong>文档版本</strong>：2026-05-16<br><strong>关联需求</strong>：<code>原始需求/系统管理/代码生成-需求文档.md</code><br><strong>关联设计</strong>：<code>docs/superpowers/specs/2026-05-16-operlog-design.md</code>（C7 列表、POST 删改、Flyway 菜单模式）<br><strong>参考实现</strong>：<code>原始需求/old/quick-boot</code>（<code>generator</code> 包、<code>CodeGenerator</code>、<code>template2</code>）、<code>原始需求/old/quick-ui/src/views/tool/gen</code></p>`,72)])])}const h=o(a,[["render",r]]);export{b as __pageData,h as default};
